<?php
declare(strict_types=1);
require_once __DIR__.'/unsubscribe-store.php';
header('Cache-Control: no-store, max-age=0');header('X-Robots-Tag: noindex, nofollow, noarchive');header('X-Content-Type-Options: nosniff');header('Referrer-Policy: no-referrer');header("Content-Security-Policy: default-src 'none'; style-src 'unsafe-inline'; form-action 'self'; base-uri 'none'; frame-ancestors 'none'");
$token=(string)(($_SERVER['REQUEST_METHOD']??'')==='POST'?($_POST['token']??''):($_GET['token']??''));$valid=preg_match('/^[a-f0-9]{64}$/',$token)===1;$completed=false;if(($_SERVER['REQUEST_METHOD']??'')==='POST'&&$valid){try{$completed=kalite_filo_consume_unsubscribe_token($token);}catch(Throwable $e){error_log('Unsubscribe failed: '.$e->getMessage());}}elseif(!in_array($_SERVER['REQUEST_METHOD']??'',['GET','POST'],true)){http_response_code(405);}
?><!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Abonelikten Ayrıl | Kalite Filo</title><style>body{margin:0;background:#101a33;color:#fff;font-family:Arial,sans-serif;display:grid;min-height:100vh;place-items:center}.card{width:min(90%,32rem);background:#fff;color:#101a33;border-radius:18px;padding:2rem;box-sizing:border-box}.button{display:block;width:100%;border:0;border-radius:10px;background:#f6a623;color:#101a33;padding:1rem;font-weight:700;cursor:pointer}p{line-height:1.6;color:#526077}</style></head><body><main class="card"><h1><?php echo $completed?'Abonelik sonlandırıldı':'E-posta aboneliği';?></h1><?php if($completed):?><p>Talebiniz kaydedildi. Gelecekteki pazarlama e-postalarından çıkarıldınız.</p><?php elseif($valid):?><p>Pazarlama e-postalarından ayrılmak için aşağıdaki işlemi onaylayın.</p><form method="post"><input type="hidden" name="token" value="<?php echo htmlspecialchars($token,ENT_QUOTES,'UTF-8');?>"><button class="button">Abonelikten Ayrıl</button></form><?php else:?><p>Bu abonelikten ayrılma bağlantısı geçerli değil.</p><?php endif;?></main></body></html>
